00042 void GFXScreen::initialize() {
00043 #ifdef M5_CORE2
00044   // Change touch screen buttons slightly to overlap with button indicators
00045   M5.BtnA.set(10, 230, 90, 50);
00046   M5.BtnB.set(115, 230, 90, 50);
00047   M5.BtnC.set(220, 230, 90, 50);
