00050   _saver.createSprite(static_cast<int16_t>(4 + SCREENSAVER_TEXT_LENGTH), 12);
00051   _saver.fillScreen(LCD_COLOR_BACKGROUND);
00052   _saver.drawString(SCREENSAVER_TEXT, 2, 2, &fonts::Font0);
00053   _screen = &BootScreen_i;
00054   _screen->enter_screen(_controller);
00055   set_screen_status(e_screen_status_on);
00056   clear();
