00059 void GFXScreen::set_screen_status(ScreenStatus status) {
00060   _screen_status = status;
00061   switch (_screen_status) {
00062     case e_screen_status_on:
00063       setBrightness(LEVEL_BRIGHT);
00064       break;
00065     case e_screen_status_dim:
00066       setBrightness(LEVEL_DIMMED);
00067       break;
00068     case e_screen_status_off:
00069       clear();
00070       if (_settings.get_animated_screensaver()) {
00071         setBrightness(LEVEL_DIMMED);
00072       } else {
00073         setBrightness(LEVEL_BLANKED);
00074       }
00075       break;
00076   }
00077 }
00078 
00079 //setup brightness by Rob Oudendijk 2023-03-13
00080 void GFXScreen::setBrightness(uint8_t lvl) {
00081 
00082   if (lvl == LEVEL_BLANKED) {
00083     // Turn screen off
00084     M5.Lcd.setBrightness(0);
00085 #ifdef M5_CORE2
00086     M5.Power.Axp192.setDCDC3(false);
00087     M5.Axp.SetDCDC3(false);
00088     M5.Axp.ScreenBreath(0);
00089 #elif M5_BASIC
00090     M5.Lcd.setBrightness(0);
00091 #endif
00092   } else {
00093 #ifdef M5_CORE2
00094     // Make sure screen is turned on
00095     M5.Axp.SetDCDC3(true);
00096     // Set brightness
00097     M5.Axp.ScreenBreath(lvl);
00098 #elif M5_BASIC
00099     if (lvl == LEVEL_BRIGHT)
00100       M5.Lcd.setBrightness(200);
00101     if (lvl == LEVEL_DIMMED || lvl == LEVEL_BLANKED)
00102       M5.Lcd.setBrightness(1);
00103 #endif
00104   }
00105 }
