00107 void GFXScreen::clear() {
00108   // Clear display
00109 
00110   M5.Lcd.startWrite();
00111   M5.Lcd.clear();
00112   M5.Lcd.setTextDatum(BL_DATUM);  // By default, text x,y is bottom left corner
00113   M5.Lcd.setTextFont(1);
00114   if (_screen) {
00115     _screen->force_next_render();
00116   }
00117   if (_menu) {
00118     _menu->force_next_render();
00119   }
00120   M5.Lcd.endWrite();
00121 
00122 }
