00124 void GFXScreen::handle_report(const worker_map_t& workers, const handler_map_t& handlers) {
00125   if (_screen) {
00126 
00127     // Keep track of screen interaction / wake up
00128     const auto button1 = workers.worker<ZenButton>(k_worker_button_1);
00129     const auto button2 = workers.worker<ZenButton>(k_worker_button_2);
00130     const auto button3 = workers.worker<ZenButton>(k_worker_button_3);
00131 
00132     if (button1->is_fresh() || button2->is_fresh() || button3->is_fresh() || (M5.Touch.isEnabled() && M5.Touch.getCount())) {
00133       _last_interaction = millis();
00134     }
00135 
00136     // Will be set false when returning from wake up
00137     bool handle_input = true;
00138 
00139     switch (_screen_status) {
00140       case e_screen_status_on:
00141         if (TIMEOUT_PASSED(_settings.get_screen_dim_timeout(), _last_interaction)) {
00142           set_screen_status(e_screen_status_dim);
00143         }
00144         else if (TIMEOUT_PASSED(_settings.get_screen_off_timeout(), _last_interaction)) {
00145           set_screen_status(e_screen_status_off);
00146         }
00147         break;
00148       case e_screen_status_dim:
00149         if (millis() - _last_interaction < (LCD_REFRESH_RATE + 1000)) {
00150           set_screen_status(e_screen_status_on);
00151         }
00152         else if (TIMEOUT_PASSED(_settings.get_screen_off_timeout(), _last_interaction)) {
00153           set_screen_status(e_screen_status_off);
00154         }
00155         break;
00156       case e_screen_status_off:
00157         if (millis() - _last_interaction < (LCD_REFRESH_RATE + 1000)) {
00158           clear();
00159           set_screen_status(e_screen_status_on);
00160           handle_input = false;
00161         }
00162         break;
00163     }
00164 
00165     if (_screen_status == e_screen_status_off) {
00166       return render_screensaver();
00167     }
00168 
00169     BaseScreen* new_screen = nullptr;
00170     if (handle_input && workers.any_updates()) {
00171       if (_menu->menu_open()) {
00172         new_screen = _menu->handle_input(_controller, workers);
00173         if (new_screen || !_menu->menu_open()) {
00174           // Closed menu
00175           M5_LOGD("Menu closed");
00176           _menu->leave_screen(_controller);
00177           clear();
00178         }
00179       } else if (_screen) {
00180         new_screen = _screen->handle_input(_controller, workers);
00181         if (new_screen == _menu) {
00182           // opened menu, not a new screen
00183           M5_LOGD("Menu opened");
00184           clear();
00185           _menu->enter_screen(_controller);
00186           new_screen = nullptr;
00187         } else if (new_screen == &DefaultEntryScreen_i) {
00188           // entered the default entry screen, handle it right away, no need to render this
00189           new_screen = new_screen->handle_input(_controller, workers);
00190         }
00191       }
00192       if (new_screen && new_screen != _screen) {
00193         M5_LOGD("New screen entered: %s", new_screen->get_title());
00194         _screen->leave_screen(_controller);
00195         _screen = new_screen;
00196         clear();
00197         _screen->enter_screen(_controller);
00198 
00199         // Check if operational mode and save
00200         if (new_screen == &DriveModeScreen_i) {
00201           _settings.set_last_mode(LocalStorage::e_operational_mode_drive, false);
00202         }
00203         if (new_screen == &SurveyModeScreen_i) {
00204           _settings.set_last_mode(LocalStorage::e_operational_mode_survey, false);
00205         }
00206         if (new_screen == &FixedModeScreen_i) {
00207           _settings.set_last_mode(LocalStorage::e_operational_mode_fixed, false);
00208         }
00209         if (new_screen == &SatelliteViewScreen_i) {
00210           _settings.set_last_mode(LocalStorage::e_operational_mode_satellite, false);
00211         }
00212 
00213       }
00214     }
00215 
00216     if (workers.any_updates() || handlers.any_updates() || (millis() - _last_render > LCD_REFRESH_RATE)) {
00217       M5.Lcd.startWrite();
00218       M5.Lcd.setRotation(3);
00219       if (_menu->menu_open()) {
00220         _menu->do_render(workers, handlers);
00221       } else {
00222         _screen->do_render(workers, handlers);
00223       }
00224 
00225       if (_screen->has_status_bar()) {
00226         // Render message if available on top of bar
00227         if (_screen->get_error_message(workers, handlers)) {
00228           M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_ERROR);
00229           uint16_t text_width = M5.Lcd.drawString(_screen->get_error_message(workers, handlers), 0, 220, &fonts::Font2);
00230           M5.Lcd.fillRect(text_width, 200, 320 - text_width, 20, LCD_COLOR_BACKGROUND);
00231         } else if (_screen->get_status_message(workers, handlers)) {
00232           M5.Lcd.setTextColor(LCD_COLOR_BACKGROUND, LCD_COLOR_DEFAULT);
00233           uint16_t text_width = M5.Lcd.drawString(_screen->get_status_message(workers, handlers), 0, 220, &fonts::Font2);
00234           M5.Lcd.fillRect(text_width, 200, 320 - text_width, 20, LCD_COLOR_BACKGROUND);
00235         } else {
00236           M5.Lcd.fillRect(0, 200, 320, 20, LCD_COLOR_BACKGROUND);
00237         }
00238 
00239         // Render bottom status bar
00240         M5.Lcd.drawLine(0, 220, 320, 220, TFT_WHITE);
00241         M5.Lcd.setFont(&fonts::Font0);
00242 
00243         // Screen name
00244         M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
00245         M5.Lcd.setCursor(0, 235);
00246         M5.Lcd.print(_screen->get_title());
00247         M5.Lcd.print(" ");
00248 
00249         // Status icon: Battery
00250         const auto& battery = workers.worker<BatteryIndicator>(k_worker_battery_indicator)->get_data();
00251         M5.Lcd.setTextColor(battery.isCharging ? LCD_COLOR_ACTIVITY : LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
00252         M5.Lcd.printf("%d%% ", battery.percentage);
00253 
00254         // Status icon: Geiger Tube
00255         const auto& gm = workers.worker<GeigerCounter>(k_worker_gm_sensor);
00256         if (!gm->active()) {
00257           M5.Lcd.setTextColor(_screen->has_required_tube() ? LCD_COLOR_ERROR : LCD_COLOR_INACTIVE, TFT_BLACK);
00258         } else {
00259           M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
00260         }
00261         M5.Lcd.print("GM ");
00262 
00263         // Status icon: GPS
00264         const auto& gps = workers.worker<GpsConnector>(k_worker_gps_connector);
00265         if (!gps->active()) {
00266           M5.Lcd.setTextColor(_screen->has_required_gps() ? LCD_COLOR_ERROR : LCD_COLOR_INACTIVE, TFT_BLACK);
00267           M5.Lcd.printf("GPS ");
00268         } else {
00269           M5.Lcd.setTextColor(gps->get_data().location_valid ? LCD_COLOR_ACTIVITY : LCD_COLOR_STALE_INCOMPLETE, TFT_BLACK);
00270           M5.Lcd.printf("GPS%d ", gps->get_data().satsInView);
00271         }
00272 
00273         // Status icon: SD
00274         if (!SDInterface::i().can_write_logs()) {
00275           M5.Lcd.setTextColor(_screen->has_required_sd() ? LCD_COLOR_ERROR : LCD_COLOR_INACTIVE, TFT_BLACK);
00276         } else {
00277           M5.Lcd.setTextColor(SDInterface::i().just_wrote() ? LCD_COLOR_ACTIVITY : LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
00278         }
00279         M5.Lcd.print("SD ");
00280 
00281         // Status icon: Wi-Fi
00282         if (WiFiWrapper_i.wifi_connected()) {
00283           M5.Lcd.setTextColor(WiFiWrapper_i.was_active() ? LCD_COLOR_ACTIVITY : LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
00284         } else {
00285           M5.Lcd.setTextColor(_screen->has_required_wifi() ? LCD_COLOR_ERROR : LCD_COLOR_INACTIVE, LCD_COLOR_BACKGROUND);
00286         }
00287         M5.Lcd.print("WF ");
00288 
00289         // Status icon: Bluetooth
00290         const auto& bt_reporter = handlers.handler<BluetoothReporter>(k_handler_bluetooth_reporter);
00291         if (bt_reporter->active()) {
00292           M5.Lcd.setTextColor(bt_reporter->client_count() > 0 ? LCD_COLOR_ACTIVITY : LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
00293         } else {
00294           M5.Lcd.setTextColor(_screen->has_required_ble() ? LCD_COLOR_ERROR : LCD_COLOR_INACTIVE, LCD_COLOR_BACKGROUND);
00295         }
00296         M5.Lcd.print("BT ");
00297 
00298         // Device
00299         if (_settings.get_device_id() < 10000) {
00300           // 4-digit device id
00301           M5.Lcd.setCursor(186, 235);
00302           M5.Lcd.setTextColor(_settings.get_device_id() ? LCD_COLOR_DEFAULT : LCD_COLOR_ERROR, LCD_COLOR_BACKGROUND);
00303           M5.Lcd.printf("#%04d ", _settings.get_device_id());
00304         } else {
00305           // 5-digit device id
00306           M5.Lcd.setCursor(180, 235);
00307           M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
00308           M5.Lcd.printf("#%5d ", _settings.get_device_id());
00309         }
00310 
00311         // Time HH:MM
00312         const auto& rtc = workers.worker<DateTimeProvider>(k_worker_rtc_connector)->get_data();
00313         M5.Lcd.setTextColor(rtc.valid ? LCD_COLOR_DEFAULT : LCD_COLOR_STALE_INCOMPLETE, LCD_COLOR_BACKGROUND);
00314         M5.Lcd.printf("%04d/%02d/%02d %02d:%02d", rtc.year, rtc.month, rtc.day, rtc.hour, rtc.minute);
00315       }
00316 
00317       M5.Lcd.setRotation(1);
00318       M5.Lcd.display();
00319       M5.Lcd.endWrite();
00320       _last_render = millis();
00321 
00322     }
00323   }
00324 
00325 }
