00327 void GFXScreen::render_screensaver() {
00328   if (_settings.get_animated_screensaver() && millis() - _last_render > 75) {
00329     M5.Lcd.setRotation(3);
00330     if (_saver_x + _saver_x_direction < -2 || _saver_x + _saver_x_direction > 318 - SCREENSAVER_TEXT_LENGTH) {
00331       _saver_x_direction *= -1;
00332     }
00333     if (_saver_y + _saver_y_direction < -2 || _saver_y + _saver_y_direction > 230) {
00334       _saver_y_direction *= -1;
00335     }
00336     _saver_x += _saver_x_direction;
00337     _saver_y += _saver_y_direction;
00338     _saver.pushSprite(_saver_x, _saver_y, TFT_TRANSPARENT);
00339     M5.Lcd.setRotation(1);
00340     _last_render = millis();
00341   }
00342 }
